#include <stdio.h>
#include <unistd.h>
#include <sys/wait.h>
int main(void) {
    pid_t pid = fork();
    if (pid == 0) {
        execlp("echo", "echo", "hello from the child via exec", (char *)NULL);
        return 1;               /* only reached if exec fails */
    }
    int status;
    waitpid(pid, &status, 0);
    printf("child exit status: %d\n", WEXITSTATUS(status));
    return 0;
}
